practical_css_blueprint:
/* ROYAL BLUE + PLATINUM FLAGSHIP BANNER OVERRIDE */
.exam-home .flagship-banner {
  background: linear-gradient(135deg, #06112E 0%, #0B1D4F 42%, #18357A 78%, #091333 100%) !important;
  border: 1px solid rgba(226, 232, 240, 0.4) !important;
  box-shadow: 0 20px 50px rgba(11, 29, 79, 0.65), 0 0 35px rgba(59, 130, 246, 0.3), inset 0 1px 2px rgba(255, 255, 255, 0.45) !important;
  position: relative;
  overflow: hidden;
}
.exam-home .flagship-banner::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(120deg, rgba(255,255,255,0.3) 0%, rgba(226,232,240,0.12) 30%, transparent 60%, rgba(191,219,254,0.25) 100%);
  pointer-events: none;
}

/* DISTINCT POLISHED METALLIC FACES FOR EACH EXAM CARD */
.exam-home .bold-exam-card {
  position: relative;
  overflow: hidden;
  border-radius: 16px;
  transition: transform 0.3s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.3s ease;
}

/* JEE Main Card - Royal Ruby Platinum */
.exam-home .bold-exam-card[data-exam='jee-main'],
.exam-home .bold-exam-card:nth-child(1) {
  background: linear-gradient(145deg, #1A070A 0%, #0D0C10 50%, #24090E 100%) !important;
  border: 1px solid rgba(230, 57, 70, 0.5) !important;
  box-shadow: 0 14px 36px rgba(0, 0, 0, 0.8), 0 0 22px rgba(230, 57, 70, 0.22), inset 0 1px 1px rgba(255, 255, 255, 0.35) !important;
}
.exam-home .bold-exam-card[data-exam='jee-main']::before,
.exam-home .bold-exam-card:nth-child(1)::before {
  content: ''; position: absolute; inset: 0;
  background: linear-gradient(125deg, rgba(230,57,70,0.25) 0%, rgba(255,255,255,0.20) 25%, transparent 55%, rgba(220,38,38,0.15) 100%);
  pointer-events: none;
}

/* BITSAT Card - Royal Cobalt Platinum */
.exam-home .bold-exam-card[data-exam='bitsat'],
.exam-home .bold-exam-card:nth-child(2) {
  background: linear-gradient(145deg, #071224 0%, #0C0D13 50%, #0A1C38 100%) !important;
  border: 1px solid rgba(56, 189, 248, 0.5) !important;
  box-shadow: 0 14px 36px rgba(0, 0, 0, 0.8), 0 0 22px rgba(56, 189, 248, 0.22), inset 0 1px 1px rgba(255, 255, 255, 0.35) !important;
}
.exam-home .bold-exam-card[data-exam='bitsat']::before,
.exam-home .bold-exam-card:nth-child(2)::before {
  content: ''; position: absolute; inset: 0;
  background: linear-gradient(125deg, rgba(56,189,248,0.25) 0%, rgba(255,255,255,0.22) 25%, transparent 55%, rgba(37,99,235,0.18) 100%);
  pointer-events: none;
}

/* COMEDK Card - Emerald Gold Titanium */
.exam-home .bold-exam-card[data-exam='comedk'],
.exam-home .bold-exam-card:nth-child(3) {
  background: linear-gradient(145deg, #061B14 0%, #0C0D11 50%, #092B1E 100%) !important;
  border: 1px solid rgba(52, 211, 153, 0.5) !important;
  box-shadow: 0 14px 36px rgba(0, 0, 0, 0.8), 0 0 22px rgba(52, 211, 153, 0.22), inset 0 1px 1px rgba(255, 255, 255, 0.35) !important;
}
.exam-home .bold-exam-card[data-exam='comedk']::before,
.exam-home .bold-exam-card:nth-child(3)::before {
  content: ''; position: absolute; inset: 0;
  background: linear-gradient(125deg, rgba(52,211,153,0.22) 0%, rgba(254,240,138,0.20) 30%, transparent 60%, rgba(16,185,129,0.18) 100%);
  pointer-events: none;
}

/* PAUSE SHINE & REDUCED MOTION SUPPORT */
.pause-shine .bold-exam-card::before,
.pause-shine .flagship-banner::before {
  animation: none !important;
  opacity: 0.6;
}
